bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
test "$(docker inspect "$cid" --format '{{.Image}}')" = "$(docker image inspect create-videobot:creator-top-8bb60a13-stage --format '{{.Id}}')" || exit 63
docker exec -i "$cid" node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {menuPage} from '/opt/videobot/src/telegram/menuPanel.mjs';
const h=menuPage('home'), p=menuPage('purchase');
assert.deepEqual(h.reply_markup.inline_keyboard.map(row=>row.map(b=>b.text)),[
  ['🎬 動画','🎨 ステッカー／絵文字'],
  ['🔙 戻る','⭐ 売上・引き出し','⭐ 購入']
]);
assert.equal(h.reply_markup.inline_keyboard[1][0].url,'https://t.me/c/2373696859/1613');
assert.equal(h.reply_markup.inline_keyboard[1][1].callback_data,'menu:sales');
assert.equal(h.reply_markup.inline_keyboard[1][2].callback_data,'menu:purchase');
assert.deepEqual(p.reply_markup.inline_keyboard[0].map(x=>x.url),['https://t.me/PremiumBot','https://fragment.com/stars']);
assert.equal(p.reply_markup.inline_keyboard[1][0].callback_data,'menu:home');
assert.match(h.text,/売上・履歴/);
assert.match(h.text,/購入先（Telegram／Fragment）/);
assert.match(p.text,/価格や支払条件を確認/);
console.log('CREATOR_TOP_INDEPENDENT_MENU_READBACK=PASS');
NODE
docker exec "$cid" grep -Fq "code==='menu:purchase'" /opt/videobot/src/telegram/creatorWizard.mjs || exit 64
docker logs "$cid" 2>&1 | grep -Fq 'CREATOR_DM_POLL_READY=PASS' || exit 65
docker logs "$cid" 2>&1 | grep -Fq 'STICKER_SHOP_HTTP_READY=PASS' || exit 66
echo 'CREATOR_TOP_PRODUCTION_INDEPENDENT_READBACK=PASS'
